cd "$(pwd)" && python3 -c "
import warnings; warnings.filterwarnings('ignore')
import hopsworks, hopsworks_common
project = hopsworks.login()
client = hopsworks_common.client.get_instance()
print('client type:', type(client).__name__)
for a in dir(client):
    if any(k in a.lower() for k in ['host','port','cert','token','key','trust','jwt','url','project']) and not a.startswith('__'):
        try:
            v = getattr(client,a)
            if not callable(v): print(a, '=', repr(v)[:120])
        except Exception as e: pass
